#include <stdio.h>
int p[6];
int find(int x){ while(p[x]!=x){ p[x]=p[p[x]]; x=p[x]; } return x; }
int main(void){
    int n=6; for (int i=0;i<n;i++) p[i]=i;
    int rel[][2]={{0,1},{1,2},{3,4}}; int nr=3;
    for (int e=0;e<nr;e++) p[find(rel[e][0])]=find(rel[e][1]);
    int reps[6], cnt=0;
    for (int i=0;i<n;i++){ int r=find(i), f=0; for(int c=0;c<cnt;c++) if(reps[c]==r) f=1; if(!f) reps[cnt++]=r; }
    printf("distinct equivalence classes = %d\n", cnt);
    for (int i=0;i<n;i++) printf("%d->%d ", i, find(i));
    printf("\n");
    return 0;
}
